    11→ * Mutation to remove a member from the organization.
    12→ */
    13→export function useRemoveMember() {
    14→	const queryClient = useQueryClient();
    15→
    16→	return useMutation({
    17→		mutationFn: async ({ memberIdOrEmail }: { memberIdOrEmail: string }) => {
    18→			await authClient.organization.removeMember({
    19→				memberIdOrEmail,
    20→			});
    21→		},
    22→		onSuccess: () => {
    23→			queryClient.invalidateQueries({ queryKey: ["organization", "members"] });
    24→			toast.success("Member removed successfully");
    25→		},
    26→		onError: (error: Error) => {
    27→			toast.error(error.message || "Failed to remove member");
    28→		},
    29→	});
    30→}
