"use client";

import * as React from "react";
import { Building2, Users, Mail } from "lucide-react";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";

import { authClient } from "@/lib/auth-client";
import {
	MemberList,
	InvitationList,
	InviteMemberDialog,
	useOrganizationMembers,
	useInvitations,
	useRemoveMember,
	useUpdateMemberRole,
	useCancelInvitation,
	type MemberRole,
} from "@/components/organization";

function getCurrentUserRole(
	members: Array<{ userId: string; role: MemberRole }>,
	currentUserId: string,
): MemberRole {
	const member = members.find((m) => m.userId === currentUserId);
	return member?.role ?? "member";
}

export default function OrganizationSettingsPage() {
	const { data: session, isPending: isSessionLoading } = authClient.useSession();

	const {
		members,
		isLoading: isMembersLoading,
		refetch: refetchMembers,
	} = useOrganizationMembers();

	const {
		invitations,
		isLoading: isInvitationsLoading,
		refetch: refetchInvitations,
	} = useInvitations();

	const removeMember = useRemoveMember();
	const updateMemberRole = useUpdateMemberRole();
	const cancelInvitation = useCancelInvitation();

	const [cancelingId, setCancelingId] = React.useState<string | null>(null);

	const currentUserId = session?.user?.id;
	const currentUserRole = currentUserId
		? getCurrentUserRole(members, currentUserId)
		: "member";

	const canManage = currentUserRole === "owner" || currentUserRole === "admin";

	const handleRemoveMember = async (memberIdOrEmail: string) => {
		await removeMember.mutateAsync({ memberIdOrEmail });
		refetchMembers();
	};

	const handleUpdateRole = async (memberId: string, role: MemberRole) => {
		await updateMemberRole.mutateAsync({ memberId, role });
		refetchMembers();
	};

	const handleCancelInvitation = async (invitationId: string) => {
		setCancelingId(invitationId);
		try {
			await cancelInvitation.mutateAsync({ invitationId });
			refetchInvitations();
		} finally {
			setCancelingId(null);
		}
	};

	const handleInviteSuccess = () => {
		refetchInvitations();
	};

	// Loading state
	if (isSessionLoading) {
		return (
			<div className="container py-6">
				<div className="space-y-6">
					<div className="space-y-2">
						<Skeleton className="h-8 w-48" />
						<Skeleton className="h-4 w-64" />
					</div>
					<Skeleton className="h-96 w-full" />
				</div>
			</div>
		);
	}

	// Not in an organization
	if (!session?.session?.activeOrganizationId) {
		return (
			<div className="container py-6">
				<div className="flex flex-col items-center justify-center py-12 text-center">
					<Building2 className="mb-4 h-12 w-12 text-muted-foreground" />
					<h2 className="mb-2 text-xl font-semibold">No Organization</h2>
					<p className="text-muted-foreground mb-4">
						You need to create or join an organization to access settings.
					</p>
					<Button render={<a href="/onboarding" />}>Create Organization</Button>
				</div>
			</div>
		);
	}

	const organizationName =
		session.session.activeOrganization?.name ?? "Organization";

	return (
		<div className="container py-6">
			<div className="mb-6 space-y-1">
				<h1 className="text-2xl font-semibold">{organizationName}</h1>
				<p className="text-muted-foreground text-sm">
					Manage your organization members and invitations
				</p>
			</div>

			<Tabs defaultValue="members">
				<TabsList className="mb-4">
					<TabsTrigger value="members">
						<Users className="mr-1.5 h-4 w-4" />
						Members
					</TabsTrigger>
					<TabsTrigger value="invitations">
						<Mail className="mr-1.5 h-4 w-4" />
						Invitations
					</TabsTrigger>
				</TabsList>

				<TabsContent value="members">
					<div className="space-y-4">
						{canManage && (
							<div className="flex justify-end">
								<InviteMemberDialog onSuccess={handleInviteSuccess} />
							</div>
						)}
						<MemberList
							members={members}
							currentUserId={currentUserId ?? ""}
							currentUserRole={currentUserRole}
							isLoading={isMembersLoading}
							onRemoveMember={handleRemoveMember}
							onUpdateRole={handleUpdateRole}
							isRemovingMember={removeMember.isPending}
						/>
					</div>
				</TabsContent>

				<TabsContent value="invitations">
					<div className="space-y-4">
						{canManage && (
							<div className="flex justify-end">
								<InviteMemberDialog onSuccess={handleInviteSuccess} />
							</div>
						)}
						<InvitationList
							invitations={invitations}
							isLoading={isInvitationsLoading}
							onCancelInvitation={handleCancelInvitation}
							isCanceling={cancelingId}
						/>
					</div>
				</TabsContent>
			</Tabs>
		</div>
	);
}

