    21→export default function OrganizationSettingsPage() {
    22→	const sessionQuery = authClient.useSession();
    23→	const {
    24→		members,
    25→		isLoading: isLoadingMembers,
    26→		refetch: refetchMembers,
    27→	} = useOrganizationMembers();
    28→	const {
    29→		invitations,
    30→		isLoading: isLoadingInvitations,
    31→		refetch: refetchInvitations,
    32→	} = useInvitations();
    33→
    34→	const removeMemberMutation = useRemoveMember();
    35→	const updateRoleMutation = useUpdateMemberRole();
    36→	const cancelInvitationMutation = useCancelInvitation();
    37→
    38→	const [cancelingId, setCancelingId] = React.useState<string | null>(null);
    39→
    40→	// Get current user's ID
    41→	const currentUserId = sessionQuery.data?.user?.id ?? "";
    42→	const hasActiveOrganization =
    43→		!!sessionQuery.data?.session?.activeOrganizationId;
    44→
    45→	// Find current user's role from members list
    46→	const currentUserRole: MemberRole = React.useMemo(() => {
    47→		const member = members.find((m) => m.userId === currentUserId);
    48→		return member?.role ?? "member";
    49→	}, [members, currentUserId]);
    50→
    51→	// Check if current user can manage members/invitations
    52→	const canManage = currentUserRole === "owner" || currentUserRole === "admin";
    53→
    54→	// Handle remove member
    55→	const handleRemoveMember = (memberIdOrEmail: string) => {
    56→		removeMemberMutation.mutate(
    57→			{ memberIdOrEmail },
    58→			{
    59→				onSuccess: () => {
    60→					refetchMembers();
    61→				},
    62→			},
    63→		);
    64→	};
    65→
    66→	// Handle update role
    67→	const handleUpdateRole = (
    68→		memberId: string,
    69→		role: "owner" | "admin" | "member",
    70→	) => {
    71→		updateRoleMutation.mutate(
    72→			{ memberId, role },
    73→			{
    74→				onSuccess: () => {
    75→					refetchMembers();
    76→				},
    77→			},
    78→		);
    79→	};
    80→
    81→	// Handle cancel invitation
    82→	const handleCancelInvitation = async (invitationId: string) => {
    83→		setCancelingId(invitationId);
    84→		try {
    85→			await cancelInvitationMutation.mutateAsync({ invitationId });
    86→			refetchInvitations();
    87→		} finally {
    88→			setCancelingId(null);
    89→		}
    90→	};
    91→
    92→	// Loading state
    93→	if (sessionQuery.isPending) {
    94→		return (
    95→			<div className="flex min-h-[50vh] items-center justify-center">
    96→				<div className="text-center">
    97→					<Spinner className="mx-auto mb-4 h-8 w-8" />
    98→					<p className="text-muted-foreground text-sm">
    99→						Loading organization...
   100→					</p>
   101→				</div>
   102→			</div>
   103→		);
   104→	}
   105→
   106→	// No active organization
   107→	if (!hasActiveOrganization) {
   108→		return (
   109→			<div className="flex min-h-[50vh] items-center justify-center">
   110→				<div className="text-center">
   111→					<Building2 className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
   112→					<h2 className="mb-2 font-semibold text-lg">No Organization Found</h2>
   113→					<p className="mb-6 text-muted-foreground text-sm">
   114→						You need to be part of an organization to access settings.
   115→					</p>
   116→				</div>
   117→			</div>
   118→		);
   119→	}
   120→
   121→	return (
   122→		<div className="mx-auto w-full max-w-6xl p-6">
   123→			{/* Page Header */}
   124→			<div className="mb-8">
   125→				<div className="flex items-center justify-between">
   126→					<div>
   127→						<h1 className="font-bold text-2xl text-foreground">
   128→							Organization Settings
   129→						</h1>
   130→						<p className="text-muted-foreground">
   131→							Manage members and invitations for your organization
   132→						</p>
   133→					</div>
   134→				</div>
   135→			</div>
   136→
   137→			{/* Tabs */}
   138→			<Tabs defaultValue="members">
   139→				<TabsList variant="line" className="mb-6">
   140→					<TabsTrigger value="members">Members</TabsTrigger>
   141→					<TabsTrigger value="invitations">Invitations</TabsTrigger>
   142→				</TabsList>
   143→
   144→				{/* Members Tab */}
   145→				<TabsContent value="members" className="space-y-6">
   146→					<div className="flex items-center justify-between">
   147→						<div>
   148→							<h2 className="font-semibold text-lg">Team Members</h2>
   149→							<p className="text-muted-foreground text-sm">
   150→								Manage access and permissions for your team
   151→							</p>
   152→						</div>
   153→						{canManage && (
   154→							<InviteMemberDialog
   155→								trigger={
   156→									<Button>
   157→										<Plus className="mr-2 h-4 w-4" />
   158→										Invite Member
   159→									</Button>
   160→								}
   161→								onSuccess={() => {
   162→									refetchMembers();
   163→									refetchInvitations();
   164→								}}
   165→							/>
   166→						)}
   167→					</div>
   168→
   169→					<MemberList
   170→						members={members}
   171→						currentUserId={currentUserId}
   172→						isLoading={isLoadingMembers}
   173→						onRemoveMember={handleRemoveMember}
   174→						onUpdateRole={handleUpdateRole}
   175→						currentUserRole={currentUserRole}
   176→						isRemovingMember={removeMemberMutation.isPending}
   177→					/>
   178→				</TabsContent>
   179→
   180→				{/* Invitations Tab */}
   181→				<TabsContent value="invitations" className="space-y-6">
   182→					<div className="flex items-center justify-between">
   183→						<div>
   184→							<h2 className="font-semibold text-lg">Pending Invitations</h2>
   185→							<p className="text-muted-foreground text-sm">
   186→								{canManage
   187→									? "Manage and cancel pending invitations"
   188→									: "View pending invitations to your organization"}
   189→							</p>
   190→						</div>
   191→						{canManage && (
   192→							<InviteMemberDialog
   193→								trigger={
   194→									<Button>
   195→										<Plus className="mr-2 h-4 w-4" />
   196→										Invite Member
   197→									</Button>
   198→								}
   199→								onSuccess={() => {
   200→									refetchMembers();
   201→									refetchInvitations();
   202→								}}
   203→							/>
   204→						)}
   205→					</div>
   206→
   207→					{isLoadingInvitations ? (
   208→						<div className="flex justify-center py-12">
   209→							<Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
   210→						</div>
   211→					) : (
   212→						<InvitationList
   213→							invitations={invitations}
   214→							onCancelInvitation={handleCancelInvitation}
   215→							isCanceling={cancelingId}
   216→						/>
   217→					)}
   218→				</TabsContent>
   219→			</Tabs>
   220→		</div>
   221→	);
   222→}
   223→

