     1→import { Input } from "@/components/ui/input";
     2→import { Label } from "@/components/ui/label";
     3→import { cn } from "@/lib/utils";
     4→
     5→interface FormFieldProps {
     6→	id?: string;
     7→	label: string;
     8→	type?: string;
     9→	value: string | number;
    10→	onChange: (value: string) => void;
    11→	onBlur?: () => void;
    12→	placeholder?: string;
    13→	error?: string;
    14→	hint?: string;
    15→	required?: boolean;
    16→	disabled?: boolean;
    17→	className?: string;
    18→	inputClassName?: string;
    19→	labelClassName?: string;
    20→}
    21→
    22→export function FormField({
    23→	id,
    24→	label,
    25→	type = "text",
    26→	value,
    27→	onChange,
    28→	onBlur,
    29→	placeholder,
    30→	error,
    31→	hint,
    32→	required = false,
    33→	disabled = false,
    34→	className,
    35→	inputClassName,
    36→	labelClassName,
    37→}: FormFieldProps) {
    38→	const fieldId = id || label.toLowerCase().replace(/\s+/g, "-");
    39→
    40→	return (
    41→		<div className={cn("space-y-2", className)}>
    42→			<Label
    43→				htmlFor={fieldId}
    44→				className={cn("text-xs uppercase tracking-wide", labelClassName)}
    45→			>
    46→				{label}
    47→				{required && <span className="ml-1 text-destructive">*</span>}
    48→			</Label>
    49→			<Input
    50→				id={fieldId}
    51→				type={type}
    52→				value={value}
    53→				onChange={(e) => onChange(e.target.value)}
    54→				onBlur={onBlur}
    55→				placeholder={placeholder}
    56→				disabled={disabled}
    57→				className={cn(error && "border-destructive", inputClassName)}
    58→			/>
    59→			{hint && <p className="text-muted-foreground text-sm">{hint}</p>}
    60→			{error && <p className="text-destructive text-sm">{error}</p>}
    61→		</div>
    62→	);
    63→}
    64→

