    24→
    25→function getInitials(name: string): string {
    26→	const parts = name.trim().split(/\s+/);
    27→	if (parts.length === 1) {
    28→		return parts[0].charAt(0).toUpperCase();
    29→	}
    30→	return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase();
    31→}
    32→
    33→export default function UserMenu() {
    34→	const router = useRouter();
    35→	const { data: session, isPending } = authClient.useSession();
    36→
    37→	if (isPending) {
    38→		return <Skeleton className="size-8 rounded-full" />;
    39→	}
    40→
    41→	if (!session) {
    42→		return (
    43→			<Button
    44→				variant="outline"
    45→				nativeButton={false}
    46→				render={<Link href="/login" />}
    47→			>
    48→				Sign In
    49→			</Button>
    50→		);
    51→	}
    52→
    53→	return (
    54→		<DropdownMenu>
    55→			<DropdownMenuTrigger
    56→				render={
    57→					<Button variant="ghost" className="h-auto p-1 rounded-full">
    58→						<Avatar size="sm">
    59→							<AvatarImage
    60→								src={session.user.image ?? undefined}
    61→								alt={session.user.name ?? "User"}
    62→							/>
    63→							<AvatarFallback>
    64→								{session.user.name ? getInitials(session.user.name) : "?"}
    65→							</AvatarFallback>
    66→						</Avatar>
    67→					</Button>
    68→				}
    69→			/>
    70→			<DropdownMenuContent align="end" className="min-w-[220px] max-w-[300px]">
    71→				<DropdownMenuGroup>
    72→					<DropdownMenuLabel className="font-normal">
    73→						<div className="flex flex-col gap-1">
    74→							<p className="truncate font-medium text-sm">{session.user.name}</p>
    75→							<p className="text-muted-foreground truncate text-xs">{session.user.email}</p>
    76→						</div>
    77→					</DropdownMenuLabel>
    78→					<DropdownMenuSeparator />
    79→					<DropdownMenuItem render={<Link href="/settings/organization" />}>
    80→						<Settings className="mr-2 size-4" />
    81→						Settings
    82→					</DropdownMenuItem>
    83→					<DropdownMenuItem
    84→						variant="destructive"
    85→						onClick={() => {
    86→							authClient.signOut({
    87→								fetchOptions: {
    88→									onSuccess: () => {
    89→										router.push("/");
    90→									},
    91→								},
    92→							});
    93→						}}
    94→					>
    95→						Sign Out
    96→					</DropdownMenuItem>
    97→				</DropdownMenuGroup>
    98→			</DropdownMenuContent>
    99→		</DropdownMenu>
   100→	);
   101→}
