    32→import { useIsMobile } from "@/hooks/use-mobile";
    33→import { authClient } from "@/lib/auth-client";
    34→
    35→interface InviteMemberDialogProps {
    36→	onSuccess?: () => void;
    37→	trigger?: React.ReactNode;
    38→	open?: boolean;
    39→	onOpenChange?: (open: boolean) => void;
    40→}
    41→
    42→export function InviteMemberDialog({
    43→	onSuccess,
    44→	trigger,
    45→	open: controlledOpen,
    46→	onOpenChange,
    47→}: InviteMemberDialogProps) {
    48→	const isMobile = useIsMobile();
    49→	const [internalOpen, setInternalOpen] = React.useState(false);
    50→
    51→	const open = controlledOpen ?? internalOpen;
    52→	const setOpen = onOpenChange ?? setInternalOpen;
    53→
    54→	const form = useForm({
    55→		defaultValues: {
    56→			email: "",
    57→			role: "member" as "member" | "admin",
    58→		},
    59→		onSubmit: async ({ value }) => {
    60→			const result = await authClient.organization.inviteMember({
    61→				email: value.email,
    62→				role: value.role,
    63→			});
    64→
    65→			if (result.error) {
    66→				toast.error(result.error.message || "Failed to send invitation");
    67→				return;
    68→			}
    69→
    70→			toast.success("Invitation sent successfully");
    71→			onSuccess?.();
    72→			setOpen(false);
    73→			form.reset();
    74→		},
    75→		validators: {
    76→			onSubmit: z.object({
    77→				email: z.string().email("Invalid email address"),
    78→				role: z.enum(["member", "admin"]),
    79→			}),
    80→		},
    81→	});
    82→
    83→	const content = (
    84→		<>
    85→			{isMobile ? (
    86→				<SheetHeader>
    87→					<SheetTitle>Invite Member</SheetTitle>
    88→				</SheetHeader>
    89→			) : (
    90→				<DialogHeader>
    91→					<DialogTitle>Invite Member</DialogTitle>
    92→					<DialogDescription>
    93→						Send an invitation to join your organization
    94→					</DialogDescription>
    95→				</DialogHeader>
    96→			)}
    97→			<form
    98→				onSubmit={(e) => {
    99→					e.preventDefault();
   100→					e.stopPropagation();
   101→					form.handleSubmit();
   102→				}}
   103→				className="space-y-4"
   104→			>
   105→				<form.Field name="email">
   106→					{(field) => (
   107→						<div className="space-y-2">
   108→							<Label htmlFor="email">Email</Label>
   109→							<Input
   110→								id="email"
   111→								type="email"
   112→								value={field.state.value}
   113→								onChange={(e) => field.handleChange(e.target.value)}
   114→								onBlur={field.handleBlur}
   115→								placeholder="colleague@example.com"
   116→								className={
   117→									field.state.meta.errors[0]?.message
   118→										? "border-destructive"
   119→										: ""
   120→								}
   121→							/>
   122→							{field.state.meta.errors[0]?.message && (
   123→								<p className="text-destructive text-sm">
   124→									{field.state.meta.errors[0]?.message}
   125→								</p>
   126→							)}
   127→						</div>
   128→					)}
   129→				</form.Field>
   130→
   131→				<form.Field name="role">
   132→					{(field) => (
   133→						<div className="space-y-2">
   134→							<Label htmlFor="role">Role</Label>
   135→							<Select
   136→								value={field.state.value}
   137→								onValueChange={(value) =>
   138→									field.handleChange(value as "member" | "admin")
   139→								}
   140→							>
   141→								<SelectTrigger id="role">
   142→									<SelectValue placeholder="Select a role" />
   143→								</SelectTrigger>
   144→								<SelectContent>
   145→									<SelectItem value="member">Member</SelectItem>
   146→									<SelectItem value="admin">Admin</SelectItem>
   147→								</SelectContent>
   148→							</Select>
   149→						</div>
   150→					)}
   151→				</form.Field>
   152→
   153→				<form.Subscribe>
   154→					{(state) => (
   155→						<Button
   156→							type="submit"
   157→							className="w-full"
   158→							disabled={!state.canSubmit || state.isSubmitting}
   159→						>
   160→							{state.isSubmitting ? "Sending..." : "Send Invitation"}
   161→						</Button>
   162→					)}
   163→				</form.Subscribe>
   164→			</form>
   165→		</>
   166→	);
   167→
   168→	if (isMobile) {
   169→		return (
   170→			<Sheet open={open} onOpenChange={setOpen}>
   171→				{trigger ? (
   172→					<SheetTrigger render={trigger as React.ReactElement} />
   173→				) : null}
   174→				<SheetContent
   175→					side="bottom"
   176→					className="max-h-[90vh] overflow-y-auto rounded-t-xl"
   177→				>
   178→					{content}
   179→				</SheetContent>
   180→			</Sheet>
   181→		);
   182→	}
   183→
   184→	return (
   185→		<Dialog open={open} onOpenChange={setOpen}>
   186→			{trigger ? (
   187→				<DialogTrigger render={trigger as React.ReactElement} />
   188→			) : null}
   189→			<DialogContent>{content}</DialogContent>
   190→		</Dialog>
   191→	);
   192→}
